<template>
  <div class="exhibition-folio">
    <aside class="exhibition-folio-index">
      <header><span class="exhibition-folio-number">03</span><h3>Designing the exhibition</h3><p>I designed each exhibition to make reading a View feel like an immersive visit. Rooms, lighting and narration let people become absorbed in the material and follow it at their own pace.</p></header>
      <nav aria-label="Exhibition design details">
        <div v-for="group in studies" :key="group.id"><h4><span>{{group.id==='exhibition'?'Exhibits and':'Guidance and'}} </span><span>{{group.id==='exhibition'?'narrative':'accessibility'}}</span></h4><button v-for="feature in group.features" :key="feature.id" type="button" :aria-pressed="active.id===feature.id" @click="select(feature.id)"><ExhibitionFeatureIcon :feature="feature.id"/><span>{{feature.label}}</span></button></div>
