          <h4 v-if="!technical || !active.mechanism">{{active.title}}</h4>
          <div v-if="technical && active.mechanism" class="exhibition-folio-mechanism"><h5>{{active.mechanism.title}}</h5><p v-for="paragraph in active.mechanism.paragraphs" :key="paragraph">{{paragraph}}</p></div>
          <template v-else>
            <GalleryStudyFilm v-if="active.video" class="exhibition-study-media" :src="film(active.video)" :poster="image(active.image)" :captions="active.sound?film('audio','vtt'):undefined" :label="active.caption" :sound="active.sound"/>
            <ExpandableProjectMedia v-else class="exhibition-study-media" :title="active.title" :aspect-ratio="1920/1046"><img class="exhibition-folio-image" :src="image(active.image)" :alt="active.alt" width="1920" height="1046"/></ExpandableProjectMedia>
            <p class="exhibition-folio-description">{{active.copy}}</p>
          </template>
          <button v-if="active.mechanism" class="exhibition-folio-technical" type="button" :aria-expanded="technical" @click="technical=!technical"><span>{{technical?'Back to the design':active.mechanism.title}}</span><svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="technical" d="M16 10H4m5-5-5 5 5 5"/><path v-else d="M4 10h12m-5-5 5 5-5 5"/></svg></button>
        </section>
      </Transition>
    </div>
  </div>
</template>
<script>
import {galleryStudyFeatures,galleryStudyCollections} from '../../data/galleryDesignStudies';
import ExhibitionFeatureIcon from '../ui/ExhibitionFeatureIcon.vue';
import ExhibitionDesignPicker from '../ui/ExhibitionDesignPicker.vue';
import GalleryStudyFilm from '../ui/GalleryStudyFilm.vue';
import ExpandableProjectMedia from '../ui/ExpandableProjectMedia.vue';
import { galleryStudyImage, galleryStudyFilm } from '../../utils/galleryDesignMedia';
export default {
  components:{ExhibitionFeatureIcon,ExhibitionDesignPicker,GalleryStudyFilm,ExpandableProjectMedia},
  data:()=>({selected:'arrival',technical:false}),
  computed:{
    active(){return galleryStudyFeatures.find(feature=>feature.id===this.selected);},
    studies(){return galleryStudyCollections.filter(group=>['exhibition','atmosphere'].includes(group.id)).map(group=>({...group,features:group.ids.map(id=>galleryStudyFeatures.find(feature=>feature.id===id))}));},
  },
  methods:{
    select(id){this.selected=id;this.technical=false;},
    image:galleryStudyImage,
    film:galleryStudyFilm,
  },
};
</script>
